// The example contacts and people that appear in the site's scenes. Cartoon
// portraits unify the site; showcase portraits illustrate Create anyone. Each was
// generated by the app's own portrait generator (scripts/generate-portraits.mjs).
// Names stay the same in every language; each contact's role (`cast.<id>`) and
// "You" (`cast.you`) are messages in i18n/locales.
export type CastId = 'mila' | 'theo' | 'ivy' | 'pixel' | 'nova' | 'coco';
export type PersonId = 'you' | 'sam' | 'ana';

export interface CastMember {
  name: string;
  style: string;
  // Sender name color in group bubbles, as in the app (light, dark).
  tint: readonly [string, string];
  photo: string;
  showcasePhoto: string;
  showcaseStyle: string;
}

export const cast: Record<CastId, CastMember> = {
  mila: { name: 'Mila', style: 'Cartoon', tint: ['#b5470b', '#ffb68a'], photo: '/contacts/cartoon/mila.jpg', showcasePhoto: '/contacts/mila.jpg', showcaseStyle: 'Cartoon' },
  theo: { name: 'Theo', style: 'Cartoon', tint: ['#22577a', '#9fcdf0'], photo: '/contacts/cartoon/theo.jpg', showcasePhoto: '/contacts/theo.jpg', showcaseStyle: 'Realistic people' },
  ivy: { name: 'Ivy', style: 'Cartoon', tint: ['#1b7a3d', '#82d69a'], photo: '/contacts/cartoon/ivy.jpg', showcasePhoto: '/contacts/ivy.jpg', showcaseStyle: '3D animated movie' },
  pixel: { name: 'Pixel', style: 'Cartoon', tint: ['#5b3fa8', '#cbb8ff'], photo: '/contacts/cartoon/pixel.jpg', showcasePhoto: '/contacts/pixel.jpg', showcaseStyle: 'Custom · retro game robots' },
  nova: { name: 'Nova', style: 'Cartoon', tint: ['#a3246b', '#ffafd6'], photo: '/contacts/cartoon/nova.jpg', showcasePhoto: '/contacts/nova.jpg', showcaseStyle: 'Anime' },
  coco: { name: 'Coco', style: 'Cartoon', tint: ['#8f4e00', '#ffb95c'], photo: '/contacts/cartoon/coco.jpg', showcasePhoto: '/contacts/coco.jpg', showcaseStyle: '3D animated pets' },
};

// `you` is rendered from the `cast.you` message.
export const people: Record<PersonId, { name: string }> = {
  you: { name: 'You' },
  sam: { name: 'Sam' },
  ana: { name: 'Ana' },
};
